/** The live aci random-spawn adapter. Native chunks and collision shapes retain
 * the chosen1.20 terrain; no missing chunk is synchronously generated by a pass.
 * The separate chunk-generation/horse-herd adapter remains its own entry. */
public class SourceSpawnWorld implements SourceSpawningKernel.World {
 protected final ServerLevel level;final SourceNaturalSpawning.State owner;private List<BlockPos> strongholds;
 // Equal block-coordinate rows can refer to different players and different bounds.
 private final Map<SourceSpawningKernel.Player,ServerPlayer> players=new IdentityHashMap<>();private final SourceSpawningKernel.Rng random;
 SourceSpawnWorld(ServerLevel level,SourceNaturalSpawning.State owner){this.level=level;this.owner=owner;random=new SourceSpawningKernel.Rng(){public int nextInt(int n){return level.random.nextInt(n);}public float nextFloat(){return level.random.nextFloat();}public boolean nextBoolean(){return level.random.nextBoolean();}};}
 @Override public SourceSpawningKernel.Rng random(){return random;}
 @Override public SourceSpawningKernel.Counters counters(){return owner.counters;}
 @Override public List<SourceSpawningKernel.Player> players(){players.clear();var rows=new ArrayList<SourceSpawningKernel.Player>();for(var p:level.players()){var row=new SourceSpawningKernel.Player(p.getBlockX(),Mth.floor(p.getY()),p.getBlockZ(),!p.isSpectator()&&p.isAlive()&&!p.isRemoved());rows.add(row);players.put(row,p);}return rows;}
 @Override public boolean overworld(){return level.dimension()==Level.OVERWORLD;}@Override public boolean underworld(){return level.dimension()==WorldEvents.UNDERWORLD;}@Override public boolean daytime(){return SourceSpecialSpawns.sourceDay(level);}
 @Override public boolean newMoon(){return SourceMoonCycle.phase(level.getDayTime())==4;}@Override public boolean fullMoon(){return SourceMoonCycle.phase(level.getDayTime())==0;}
 @Override public boolean bloodMoon(boolean night){return OriginalWeather.blood(level)&&(!night||!daytime());}@Override public boolean blueMoon(boolean night){return Settings.MOONS&&overworld()&&SourceMoonCycle.blue(level.getDayTime(),night);}@Override public boolean blueMoonNight(){return blueMoon(true);}@Override public boolean thunderingForSpawn(){return (double)level.getThunderLevel(1)>.9;}
 @Override public boolean hostileAllowed(){return level.getDifficulty()!=Difficulty.PEACEFUL&&level.getServer().isSpawningMonsters();}@Override public boolean peacefulAllowed(){return level.getServer().isSpawningAnimals();}@Override public boolean spawningDisabled(){return !level.getGameRules().getBoolean(GameRules.RULE_DOMOBSPAWNING);}@Override public long timeOfDay(){return Math.floorMod(level.getDayTime(),24000);}
 @Override public boolean tournamentActive(){return SourceTournament.mode(level.getServer())!=null;}
 @Override public boolean tournamentScore(){return SourceTournament.mode(level.getServer())==SourceTournament.Mode.SCORE;}
 @Override public boolean tournamentAllowsAnimals(){var mode=SourceTournament.mode(level.getServer());return mode!=null&&mode.animals;}
 @Override public boolean tournamentArena(int x,int z){return SourceTournament.inArena(level,x,z);}
 @Override public int nearbyHostiles(SourceSpawningKernel.Player row){var p=players.get(row);var box=p==null?new AABB(row.x(),row.footY(),row.z(),row.x()+.6,row.footY()+1.8,row.z()+.6):p.getBoundingBox();return level.getEntitiesOfClass(Mob.class,box.inflate(32,8,32),mob->mob.getType().getCategory()==MobCategory.MONSTER).size();}
 @Override public float strongholdProximity(int x,int z){
  if(strongholds==null){strongholds=new ArrayList<>();var structure=level.registryAccess().registryOrThrow(Registries.STRUCTURE).getHolderOrThrow(BuiltinStructures.STRONGHOLD);var state=level.getChunkSource().getGeneratorState();for(var placement:state.getPlacementsForStructure(structure))if(placement instanceof ConcentricRingsStructurePlacement ring){var positions=state.getRingPositionsFor(ring);if(positions!=null)for(var pos:positions)strongholds.add(new BlockPos(pos.getMiddleBlockX(),64,pos.getMiddleBlockZ()));}}
  BlockPos nearest=null;double distance=Double.MAX_VALUE;for(var at:strongholds){double dx=(double)at.getX()-x,dz=(double)at.getZ()-z,sq=dx*dx+dz*dz;if(sq<distance){distance=sq;nearest=at;}}if(nearest==null)return 0;var spawn=level.getSharedSpawnPos();double dx=(double)nearest.getX()-spawn.getX(),dz=(double)nearest.getZ()-spawn.getZ(),fromSpawn=Math.sqrt(dx*dx+dz*dz);if(fromSpawn<2000)return 0;return Math.max((float)(1-Math.sqrt(distance)/fromSpawn),0);
 }
 @Override public int mobCount(boolean below,boolean upper){int count=0;for(var entity:level.getAllEntities())if(entity.getType().getCategory()==MobCategory.MONSTER&&(entity.getBlockY()<60?below:upper))count++;return count;}
 static MobCategory category(SourceSpawningKernel.Group group){return switch(group){case HOSTILE->MobCategory.MONSTER;case ANIMAL->MobCategory.CREATURE;case AMBIENT->MobCategory.AMBIENT;case AQUATIC->MobCategory.WATER_CREATURE;};}
 @Override public int count(SourceSpawningKernel.Group group){int count=0;for(var entity:level.getAllEntities())if(entity.getType().getCategory()==category(group))count++;return count;}
 @Override public void hostileLimit(boolean deep,int value){if(deep)owner.deepLimit=value;else owner.upperLimit=value;}
 @Override public int minimumY(){return level.getMinBuildHeight();}@Override public boolean chunkReady(SourceSpawningKernel.Chunk c){return level.getChunkSource().getChunkNow(c.x(),c.z())!=null;}
 @Override public int sampleHeightExclusive(SourceSpawningKernel.Chunk c){var chunk=level.getChunkSource().getChunkNow(c.x(),c.z());if(chunk==null)throw new IllegalStateException("aci sampled an unloaded chunk");return Math.max(level.getMinBuildHeight()+1,Math.min(level.getMaxBuildHeight(),chunk.getHighestSectionPosition()+16));}
 private boolean loaded(BlockPos pos){return level.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4)!=null;}
 @Override public SourceSpawningKernel.Block block(int x,int y,int z){var pos=new BlockPos(x,y,z);return new SpawnBlock(loaded(pos)?level.getBlockState(pos):Blocks.BEDROCK.defaultBlockState(),pos);}
 @Override public boolean air(int x,int y,int z){var pos=new BlockPos(x,y,z);return loaded(pos)&&level.isEmptyBlock(pos);}
 @Override public int totalLight(int x,int y,int z){return level.getMaxLocalRawBrightness(new BlockPos(x,y,z));}@Override public int skyLight(int x,int y,int z){return level.getBrightness(LightLayer.SKY,new BlockPos(x,y,z));}
 @Override public boolean playerWithin(double x,double y,double z,double range,boolean alive){for(var p:level.players())if(!p.isSpectator()&&(!alive||p.isAlive())&&p.distanceToSqr(x,y,z)<range*range)return true;return false;}
 @Override public SourceSpawningKernel.Point spawnPoint(){var p=level.getSharedSpawnPos();return new SourceSpawningKernel.Point(p.getX(),p.getY(),p.getZ());}
 @Override public boolean outdoors(int x,int y,int z){return SourceSpawnOutdoors.isOutdoors(level,new BlockPos(x,y,z));}
 WeightedRandomList<MobSpawnSettings.SpawnerData> sourcePool(SourceSpawningKernel.Group group,BlockPos pos){
  var category=category(group);WeightedRandomList<MobSpawnSettings.SpawnerData> rows;
  if(level.dimension()==Level.NETHER&&category==MobCategory.MONSTER)rows=SourceFortressSpawns.pool(level,pos);
  else rows=level.getChunkSource().getGenerator().getMobsAt(level.getBiome(pos),level.structureManager(),category,pos);
  rows=ForgeEventFactory.getPotentialSpawns(level,category,pos,rows);
  var settings=WorldContentMode.settings(level);
  return WeightedRandomList.create(rows.unwrap().stream().filter(row->SourceNaturalSpawning.sourceType(row.type)
   && RebuiltContent.allows(row.type, settings)).toList());
 }
 @Override public Object suitable(SourceSpawningKernel.Group group,int x,int y,int z){var pos=new BlockPos(x,y,z);return OriginalSpawnSelection.choose(sourcePool(group,pos),level.random,level,pos).map(row->row.type).orElse(null);}
 @Override public Object substitute(Object type){return SourceSpawnBody.substitute(level,type);}@Override public boolean vampireType(Object type){return type==Mobs.BAT.get();}@Override public boolean ghastType(Object type){return type==EntityType.GHAST;}
 @Override public SourceSpawningKernel.Actor construct(Object type){var entity=((EntityType<?>)type).create(level);if(!(entity instanceof Mob mob))throw new IllegalStateException("aci needs a living mob: "+type);return new Body(mob);}
 @Override public boolean canPlaceSelected(SourceSpawningKernel.Actor actor,Object selected,boolean light){
  var body=(Body)actor;
  return body.canSpawnHere(light,body.mob.getType()==selected);
 }
 private static final class ElitePack {
  final SpawnGroupData nativeData;
  boolean admittedElite;
  ElitePack(SpawnGroupData nativeData,boolean admittedElite){
   this.nativeData=nativeData;
   this.admittedElite=admittedElite;
  }
 }

 @Override public Object finish(SourceSpawningKernel.Actor actor,Object data){
  var body=(Body)actor;
  var pack=data instanceof ElitePack existing ? existing : null;
  var nativeData=pack==null ? (SpawnGroupData)data : pack.nativeData;
  var result=SourceSpawnInitialization.finish(body.mob,level,MobSpawnType.NATURAL,copyOrdinaryAnimalGroup(nativeData));
  body.mob=result.actor();
  if(pack==null || !pack.admittedElite)body.firstIteDay=IteEliteSpawns.firstEligibleDay(level,body.mob);
  if(pack==null && body.firstIteDay<=0)return result.data();
  var candidate=new ElitePack(result.data(),pack!=null && pack.admittedElite);
  body.elitePack=candidate;
  return candidate;
 }

 private static SpawnGroupData copyOrdinaryAnimalGroup(SpawnGroupData data){
  // Native animal finalization increments a plain group's size before the join event.
  if(data==null || data.getClass()!=AgeableMob.AgeableMobGroupData.class)return data;
  var original=(AgeableMob.AgeableMobGroupData)data;
  var copy=original.isShouldSpawnBaby()
      ? new AgeableMob.AgeableMobGroupData(original.getBabySpawnChance())
      : new AgeableMob.AgeableMobGroupData(false);
  for(int member=0;member<original.getGroupSize();member++)copy.increaseGroupSizeByOne();
  return copy;
 }

 @Override public boolean spawnNaturally(SourceSpawningKernel.Actor actor){
  var mob=((Body)actor).mob;
  if(mob.isAddedToWorld() || mob.isRemoved() || mob.level()!=level)return false;
  spawn(actor);
  return hasJoined(mob);
 }

 private boolean hasJoined(Mob mob){
  return mob.isAddedToWorld() && !mob.isRemoved() && mob.level()==level;
 }

 @Override public void spawn(SourceSpawningKernel.Actor actor){
  var body=(Body)actor;
  var mob=body.mob;
  if(mob.isSpawnCancelled())return;
  var pack=body.elitePack;
  boolean elite=pack!=null && !pack.admittedElite && IteEliteSpawns.tryMark(level,mob,body.firstIteDay);
  level.addFreshEntityWithPassengers(mob);
  if(elite && hasJoined(mob))pack.admittedElite=true;
 }
 @Override public void constructionError(Exception error){com.mojang.logging.LogUtils.getLogger().error("R195 natural mob construction",error);}
 @Override public List<SourceSpawningKernel.Entry> worldgenRows(Object biome,SourceSpawningKernel.Group group){var result=new ArrayList<SourceSpawningKernel.Entry>();for(var row:((Biome)biome).getMobSettings().getMobs(category(group)).unwrap())if(SourceNaturalSpawning.sourceType(row.type))result.add(new SourceSpawningKernel.Entry(row.type,row.getWeight().asInt(),row.minCount,row.maxCount));return result;}
 @Override public float worldgenProbability(Object biome){return ((Biome)biome).getMobSettings().getCreatureProbability();}
 @Override public boolean horseType(Object type){return type==EntityType.HORSE;}@Override public boolean ordinaryWolfType(Object type){return type==EntityType.WOLF;}
 @Override public boolean animalTypeExceptHellhound(Object type){return type instanceof EntityType<?> entity&&SourceSpawnSchedule.sourceAnimal(entity);}
 @Override public int initialY(int x,int z){return level.getHeight(Heightmap.Types.OCEAN_FLOOR_WG,x,z);}@Override public int highestWaterY(int x,int z){return level.getHeight(Heightmap.Types.WORLD_SURFACE_WG,x,z)-1;}
 @Override public int chunkAnimals(int x,int z){throw new UnsupportedOperationException("Worldgen region/quota entry is not bound yet");}@Override public void chunkAnimals(int x,int z,int value){throw new UnsupportedOperationException("Worldgen region/quota entry is not bound yet");}
 final class SpawnBlock implements SourceSpawningKernel.Block {
  final BlockState state;final BlockPos pos;SpawnBlock(BlockState state,BlockPos pos){this.state=state;this.pos=pos;}
  public SourceSpawningKernel.Material material(){return state.isAir()?SourceSpawningKernel.Material.AIR:state.getBlock() instanceof LiquidBlock?state.getFluidState().is(FluidTags.WATER)?SourceSpawningKernel.Material.WATER:state.getFluidState().is(FluidTags.LAVA)?SourceSpawningKernel.Material.LAVA:SourceSpawningKernel.Material.OTHER:SourceSpawningKernel.Material.OTHER;}
  public boolean fullStandardCube(){return SourcePhaseNativeWorld.solid(state)&&!(state.getBlock() instanceof SnowLayerBlock)&&state.isCollisionShapeFullBlock(level,pos);}public boolean solidAt(){return SourcePhaseNativeWorld.solid(state);}public double top(){var shape=state.getShape(level,pos);return shape.isEmpty()?0:shape.max(Direction.Axis.Y);}public boolean topFlatSolid(){return state.isFaceSturdy(level,pos,Direction.UP);}public boolean slabOrStairs(){return state.getBlock() instanceof SlabBlock||state.getBlock() instanceof StairBlock;}
  public boolean bedrockOrMantle(){return state.is(Blocks.BEDROCK)||state.getBlock() instanceof SourceMantleBlock;}public boolean myceliumOrLeaves(){return state.is(Blocks.MYCELIUM)||state.getBlock() instanceof LeavesBlock;}public boolean snowLayer(){return state.getBlock() instanceof SnowLayerBlock;}public boolean cactus(){return state.is(Blocks.CACTUS);}public boolean grass(){return state.is(Blocks.GRASS_BLOCK);}public boolean ice(){return state.is(Blocks.ICE);}
 }
 final class Body implements SourceSpawningKernel.Actor {
  Mob mob;private ElitePack elitePack;private int firstIteDay;Body(Mob mob){this.mob=mob;}public float width(){return mob.getBbWidth();}public float height(){return mob.getBbHeight();}public boolean bat(){return mob instanceof SourceBat;}public boolean phaseSpider(){return Mobs.name(mob).equals("phase_spider");}public boolean ghast(){return mob.getType()==EntityType.GHAST;}
  public boolean burnsInSun(){
   // R195 aci checks the undead category after placement, independently of fire immunity.
   if(mob instanceof Mobs.Undead)return mob.getMobType()==MobType.UNDEAD;
   return (mob instanceof Zombie||mob instanceof AbstractSkeleton)&&!Set.of("earth_elemental","fire_elemental","shadow","clay_golem").contains(Mobs.name(mob));
  }
  public int maximumPack(){return mob.getMaxSpawnClusterSize();}
  public float initialHang(int x,int y,int z,float px,float py,float pz){return mob instanceof SourceBat bat?bat.sourceInitialHang(x,y,z,px,py,pz):py;}
  public void move(float x,float y,float z,float yaw,float pitch){mob.moveTo(x,y,z,yaw,pitch);}public int blockX(){return mob.getBlockX();}public int eyeBlockY(){return Mth.floor(mob.getEyeY());}public int blockZ(){return mob.getBlockZ();}public void aquaticInitialDespawn(int value){OriginalDespawn.refresh(mob,value);}
  public boolean canSpawnHere(boolean light){return canSpawnHere(light,false);}
  private boolean canSpawnHere(boolean light,boolean selected){
   if(!CaveSpawnBudget.allows(mob))return false;
   var type=mob.getType();boolean aquatic=type==EntityType.SQUID,animal=SourceSpawnSchedule.sourceAnimal(type);var pos=mob.blockPosition();
   var bounds=mob.getBoundingBox().inflate(aquatic?2:0);for(int x=Mth.floor(bounds.minX)>>4;x<=Mth.floor(bounds.maxX)>>4;x++)for(int z=Mth.floor(bounds.minZ)>>4;z<=Mth.floor(bounds.maxZ)>>4;z++)if(level.getChunkSource().getChunkNow(x,z)==null)return false;
   if(aquatic){if(mob.getY()<=45||mob.getY()>=63)return false;for(var state:level.getBlockStates(mob.getBoundingBox().inflate(2)).toList())if(!(state.getBlock() instanceof LiquidBlock)||!state.getFluidState().is(FluidTags.WATER))return false;}
   else if(!(animal&&!light)){
    boolean allowed=selected?SourceSpecialSpawns.checkSelectedPlacement(type,level,pos,level.random)
     :SpawnPlacements.checkSpawnRules(type,level,MobSpawnType.NATURAL,pos,level.random);
    if(!allowed)return false;
   }
   var event=new MobSpawnEvent.PositionCheck(mob,level,MobSpawnType.NATURAL,null);MinecraftForge.EVENT_BUS.post(event);if(event.getResult()!=Event.Result.DEFAULT)return event.getResult()==Event.Result.ALLOW;
   if(!(animal&&!light)&&!mob.checkSpawnRules(level,MobSpawnType.NATURAL))return false;
   if(mob instanceof SourceBat||mob instanceof SourcePigman)return mob.checkSpawnObstruction(level);
   if(!level.isUnobstructed(mob)||!level.noCollision(mob))return false;String name=Mobs.name(mob);if(!name.equals("wood_spider")&&!name.equals("black_widow_spider")&&level.getBlockState(pos.below()).getBlock() instanceof LeavesBlock)return false;
   if(type.getCategory()==MobCategory.MONSTER){var above=level.getBlockState(pos.above());if(above.getFluidState().is(FluidTags.WATER)||level.getBlockState(pos).getFluidState().is(FluidTags.WATER)&&SourcePhaseNativeWorld.solid(above)||above.is(Blocks.CACTUS))return false;return level.getBlockStates(mob.getBoundingBox()).noneMatch(s->s.getFluidState().is(FluidTags.LAVA));}
   return aquatic||!level.containsAnyLiquid(mob.getBoundingBox());
  }
 }
}
